import json
import math
from pathlib import Path


def _reject_non_finite(token):
    raise ValueError('non-finite JSON number is not allowed: ' + token)


def load_payload(path: Path) -> object:
    """Read a UTF-8 JSON file.

    The top-level value must be a JSON object or array.  All non-finite
    numbers (NaN, Infinity, -Infinity) are rejected, including values
    nested anywhere in the document.
    """
    try:
        text = Path(path).read_text(encoding='utf-8')
        data = json.loads(text, parse_constant=_reject_non_finite)
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, (dict, list)):
        raise ValueError('top-level JSON value must be an object or array')
    return data


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _validate_no_non_finite(value):
    """Recursively reject NaN/Infinity values in any JSON data."""
    if isinstance(value, float):
        if math.isnan(value) or math.isinf(value):
            raise ValueError('non-finite numbers are not allowed')
    elif isinstance(value, dict):
        for child in value.values():
            _validate_no_non_finite(child)
    elif isinstance(value, list):
        for child in value:
            _validate_no_non_finite(child)
